void matrixMult(int *a, int *b, int *c, int N)
{
    int temp_sum;

#pragma omp parallel for collapse(2) num_threads(THREADS)
    // For every row
    for (int i = 0; i < N; i++)
    {
        // For every column
        for (int j = 0; j < N; j++)
        {
            temp_sum = 0;
            // For every element in the row-column pair
            for (int k = 0; k < N; k++)
                temp_sum += a[i * N + k] * b[k * N + j]; // Accumulate the partial results
            c[i * N + j] = temp_sum;
        }
    }
}

int calculate_pi(int argc, char **argv)
{
    // Choice the random seed
    srand(time(NULL));

    // Total points inside circle
    int sum = 0;

    // Iterations number
    int N = 256 * 256 * atoi(argv[1]);

    // Random coordinates from the range (0,1)
    double x, y;

    // Execution time - start
    auto start = high_resolution_clock::now();

// Launch sum calculation
#pragma omp parallel for private(x, y) reduction(+ : sum) num_threads(THREADS)
    for (int i = 0; i < N; i++)
    {
        x = (double)rand() / RAND_MAX;
        y = (double)rand() / RAND_MAX;

        if (x * x + y * y <= 1.0)
            sum++;
    }

    // Execution time - stop
    auto stop = high_resolution_clock::now();

    // Evaluate PI
    double pi = sum * 4.0 / N;

    // Evaluate relative error
    double err = abs(pi - acos(-1)) / pi * 100;

    /* Getting number of milliseconds as a double. */
    duration<double, std::milli> ms_double = stop - start;

    printf("\nCompleted successfully!\n");
    printf("CPU PI = %f\n", pi);
    printf("CPU relative error = %f pct\n", err);
    printf("calculatePi() execution time on the CPU: %f ms\n", ms_double.count());

    return 0;
}

// Game of life algorithm
char analyzeCell(char *c_m, int N, int i, int j)
{
    int alive_neighbours = 0, dead_neighbours = 0;

    c_m[(i - 1) * N + (j - 1)] == '.' ? dead_neighbours++ : alive_neighbours++;
    c_m[(i - 1) * N + j] == '.' ? dead_neighbours++ : alive_neighbours++;
    c_m[(i - 1) * N + (j + 1)] == '.' ? dead_neighbours++ : alive_neighbours++;
    c_m[i * N + (j + 1)] == '.' ? dead_neighbours++ : alive_neighbours++;
    c_m[(i + 1) * N + (j + 1)] == '.' ? dead_neighbours++ : alive_neighbours++;
    c_m[(i + 1) * N + j] == '.' ? dead_neighbours++ : alive_neighbours++;
    c_m[(i + 1) * N + (j - 1)] == '.' ? dead_neighbours++ : alive_neighbours++;
    c_m[i * N + (j - 1)] == '.' ? dead_neighbours++ : alive_neighbours++;

    if (alive_neighbours < 2)
        return '.';

    else if (alive_neighbours > 3)
        return '.';

    else if (c_m[i * N + j] == 'X' && (alive_neighbours == 2 || alive_neighbours == 3))
        return 'X';

    else if (c_m[i * N + j] == '.' && alive_neighbours == 3)
        return 'X';

    else
        return 'X';
}

void prefix_sum(int* a, int index, size_t n, size_t block_size, int* flag) {

    int block_num = index / block_size;

    for (int i = index + 1; i < index + block_size; ++i) {
        a[i] = a[i] + a[i - 1];
    }

    if (block_num > 0) {
        while (1) {
#pragma omp flush(flag)
            int flg_tmp = flag[block_num - 1];
            if (flg_tmp == 1) break;
        }

        //update the last element of the block prior to the elements before so that we can
        // set flag earlier for the successor blocks
        int last_element_prev_block = index - 1;
        a[index + block_size - 1] += a[last_element_prev_block];


        // after updating the last element of the block, set flag so that next block can
        // update its elements.
#pragma omp flush
        flag[block_num] = 1;
#pragma omp flush(flag)


        for (int i = index; i < index + block_size - 1; ++i) {
            a[i] = a[i] + a[last_element_prev_block];
        }
    }
    else {
#pragma omp flush
        flag[block_num] = 1;
#pragma omp flush(flag)
    }




}

void prefix_sum_parallel(int* a, size_t n, size_t block_size) {

    int* flag = (int*)malloc(NUM_THREADS * sizeof(int));

    for (int i = 0; i < NUM_THREADS; i++) {
        flag[i] = 0;
    }

    double start = omp_get_wtime();

#pragma omp parallel
    {
#pragma omp for
        for (int i = 0; i < n; i += block_size) {
            prefix_sum(a, i, n, block_size, flag);
        }

    }

    double elapsed = omp_get_wtime() - start;

    printf("Elapsed time is %f\n", elapsed);

}

